CREATE VIEW std_game_mode AS WITH mode_split AS (SELECT game_title, platform_name, main."trim"(mode_value) AS mode_value FROM std_inventory_game_ready , unnest(string_split(mode_raw, ',')) AS t(mode_value) WHERE (mode_raw IS NOT NULL)), mode_canonical AS (SELECT game_title, platform_name, CASE  WHEN ((mode_value ~~* 'Single player')) THEN ('Single Player') WHEN ((mode_value ~~* 'Split screen')) THEN ('Split Screen') ELSE mode_value END AS mode_name FROM mode_split)SELECT DISTINCT game_title, platform_name, mode_name FROM mode_canonical WHERE ((mode_name IS NOT NULL) AND (mode_name != ''));
